public class DashboardService {
    private final UserService userService;
    private final RecommendationService recommendationService;

    public DashboardResponse getDashboard(String userId) {
        CompletableFuture<UserDto> userFuture = CompletableFuture
            .supplyAsync(() -> userService.getUser(userId));

        CompletableFuture<List<RecommendationDto>> recsFuture = CompletableFuture
            .supplyAsync(() -> recommendationService.getRecommendations(userId))
            .handle((recs, ex) -> {
                if (ex != null) {
                    // Log the isolated failure and return a safe fallback
                    LoggerFactory.getLogger(DashboardService.class)
                        .warn("Failed to fetch recommendations: {}", ex.getMessage());
                    return Collections.emptyList();
                }
                return recs;
            });

        return CompletableFuture.allOf(userFuture, recsFuture)
            .thenApply(v -> new DashboardResponse(
                userFuture.join(),
                recsFuture.join(),
                recsFuture.isCompletedExceptionally() ? "Degraded recommendations" : null
            )).join();
    }
}
